{{ $json['Toutes les variables'].tableau.toSpliced(1, 1) }}
→ Supprime 1 élément à partir de l’index 1 → ["pomme", "cerise"]

{{ $json['Toutes les variables'].tableau.union(["banane", "kiwi"]) }}
→ Union sans doublons → ["pomme", "banane", "cerise", "kiwi"]

{{ $json['Toutes les variables'].tableau.unique() }}
→ Supprime les doublons → ["pomme", "banane", "cerise"]

={{ $json['Toutes les variables'].nombre.isEven() }}
