// Transformer le tableau de keywords en items individuels
const keywords = $input.first().json.keywords;
const maxResults = $input.first().json.maxResults;
const publishedAfter = $input.first().json.publishedAfter;

return keywords.map(keyword => ({
  json: {
    keyword,
    maxResults,
    publishedAfter
  }
}));

// Extraire les IDs de vidéos et dédupliquer
const allVideos = [];
const seenIds = new Set();

for (const item of $input.all()) {
  const videos = item.json.items || [];
  const keyword = item.json.keyword || 'unknown';

  for (const video of videos) {
    const videoId = video.id?.videoId;
    if (videoId && !seenIds.has(videoId)) {
      seenIds.add(videoId);
      allVideos.push({
        json: {
          videoId,
          title: video.snippet?.title,
          description: video.snippet?.description,
          channelTitle: video.snippet?.channelTitle,
          channelId: video.snippet?.channelId,
          publishedAt: video.snippet?.publishedAt,
          thumbnailUrl: video.snippet?.thumbnails?.high?.url,
          searchKeyword: keyword
        }
      });
    }
  }
}

return allVideos;

// Fusionner les données de recherche avec les statistiques
const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const statsResponse = $input.all()[i].json;
  const videoData = $('Extract Video IDs').all()[i]?.json;

  if (statsResponse.items && statsResponse.items[0] && videoData) {
    const stats = statsResponse.items[0].statistics;
    const contentDetails = statsResponse.items[0].contentDetails;

    // Parser la durée ISO 8601
    const duration = contentDetails?.duration || 'PT0S';
    const durationMatch = duration.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
    const hours = parseInt(durationMatch?.[1] || 0);
    const minutes = parseInt(durationMatch?.[2] || 0);
    const seconds = parseInt(durationMatch?.[3] || 0);
    const totalMinutes = hours * 60 + minutes + seconds / 60;

    const viewCount = parseInt(stats?.viewCount || 0);
    const likeCount = parseInt(stats?.likeCount || 0);

    // Filtrer: >5000 vues minimum
    if (viewCount >= 5000) {
      results.push({
        json: {
          ...videoData,
          viewCount,
          likeCount,
          commentCount: parseInt(stats?.commentCount || 0),
          duration: duration,
          durationMinutes: Math.round(totalMinutes * 10) / 10,
          engagementRate: viewCount > 0 ? Math.round((likeCount / viewCount) * 10000) / 100 : 0,
          videoUrl: `https://www.youtube.com/watch?v=${videoData.videoId}`
        }
      });
    }
  }
}

// Trier par vues décroissantes
results.sort((a, b) => b.json.viewCount - a.json.viewCount);

// Limiter à 50 vidéos max pour l'analyse
return results.slice(0, 50);

// Agréger toutes les vidéos en un seul objet pour l'analyse AI
const videos = $input.all().map(item => item.json);

const summary = {
  totalVideos: videos.length,
  totalViews: videos.reduce((sum, v) => sum + v.viewCount, 0),
  avgViews: Math.round(videos.reduce((sum, v) => sum + v.viewCount, 0) / videos.length),
  avgDuration: Math.round(videos.reduce((sum, v) => sum + v.durationMinutes, 0) / videos.length * 10) / 10,
  avgEngagement: Math.round(videos.reduce((sum, v) => sum + v.engagementRate, 0) / videos.length * 100) / 100,
  topChannels: [...new Set(videos.map(v => v.channelTitle))].slice(0, 10)
};

return [{
  json: {
    videos,
    summary,
    analysisDate: new Date().toISOString()
  }
}];

// Préparer les vidéos pour export Google Sheets
const videos = $('Aggregate for AI Analysis').first().json.videos;
const analysisDate = new Date().toISOString().split('T')[0];

return videos.map(video => ({
  json: {
    analysisDate,
    title: video.title,
    channel: video.channelTitle,
    viewCount: video.viewCount,
    likeCount: video.likeCount,
    engagementRate: video.engagementRate,
    durationMinutes: video.durationMinutes,
    publishedAt: video.publishedAt?.split('T')[0],
    searchKeyword: video.searchKeyword,
    videoUrl: video.videoUrl
  }
}));

